import React, { useState, useEffect } from 'react';
import { useAuth } from '../../contexts/AuthContext';
import { useInfiniteScroll } from '../../hooks/useInfiniteScroll';
import { FeedPost } from '../../components/feed/FeedPost/FeedPost.jsx';

const ConsumerDashboard = () => {
  const { user, logout } = useAuth();
  
  // Environment Variables
  const appName = import.meta.env.VITE_APP_NAME || 'MediaFeed';
  
  // Infinite scroll hook
  const {
    items: posts,
    isLoading,
    hasMore,
    lastItemRef,
    loadMore
  } = useInfiniteScroll('/posts', 5);

  // Mock data for testing
  const [mockPosts, setMockPosts] = useState([]);
  const [loading, setLoading] = useState(true);

  const mockPostsData = [
    {
      id: 1,
      title: 'Beautiful Sunset',
      caption: 'Amazing sunset at the beach!',
      location: 'Maldives',
      thumbnailUrl: 'https://picsum.photos/600/400?random=1',
      imageUrl: 'https://picsum.photos/600/400?random=1',
      type: 'image',
      isLiked: false,
      likesCount: 124,
      isBookmarked: false,
      author: {
        username: 'traveler_123',
        avatar: 'https://randomuser.me/api/portraits/women/1.jpg'
      },
      comments: [
        {
          id: 1,
          text: 'Beautiful shot!',
          user: { username: 'nature_lover' },
          createdAt: new Date().toISOString()
        }
      ],
      createdAt: new Date().toISOString()
    },
    {
      id: 2,
      title: 'Mountain Adventure',
      caption: 'Hiking in the mountains',
      location: 'Swiss Alps',
      thumbnailUrl: 'https://picsum.photos/600/400?random=2',
      imageUrl: 'https://picsum.photos/600/400?random=2',
      type: 'video',
      isLiked: true,
      likesCount: 89,
      isBookmarked: false,
      author: {
        username: 'adventurer',
        avatar: 'https://randomuser.me/api/portraits/men/2.jpg'
      },
      comments: [],
      createdAt: new Date(Date.now() - 86400000).toISOString()
    },
    {
      id: 3,
      title: 'City Lights',
      caption: 'Night view of the city',
      location: 'New York',
      thumbnailUrl: 'https://picsum.photos/600/400?random=3',
      imageUrl: 'https://picsum.photos/600/400?random=3',
      type: 'image',
      isLiked: false,
      likesCount: 56,
      isBookmarked: true,
      author: {
        username: 'city_explorer',
        avatar: 'https://randomuser.me/api/portraits/women/3.jpg'
      },
      comments: [],
      createdAt: new Date(Date.now() - 172800000).toISOString()
    }
  ];

  useEffect(() => {
    setTimeout(() => {
      setMockPosts(mockPostsData);
      setLoading(false);
    }, 500);
  }, []);

  return (
    <div style={{ minHeight: '100vh', background: '#fafafa' }}>
      {/* Header */}
      <div style={{ 
        background: 'white', 
        padding: '15px 30px', 
        display: 'flex', 
        justifyContent: 'space-between', 
        alignItems: 'center', 
        borderBottom: '1px solid #dbdbdb',
        position: 'sticky',
        top: 0,
        zIndex: 100
      }}>
        <h1 style={{ margin: 0, fontSize: '24px' }}>{appName}</h1>
        
        <div style={{ display: 'flex', alignItems: 'center', gap: '20px' }}>
          <span>Welcome, {user?.username || 'Consumer'}!</span>
          <button 
            onClick={logout} 
            style={{ 
              padding: '8px 16px', 
              backgroundColor: '#ed4956', 
              color: 'white', 
              border: 'none', 
              borderRadius: '5px', 
              cursor: 'pointer' 
            }}
          >
            Logout
          </button>
        </div>
      </div>

      {/* Feed */}
      <div style={{ maxWidth: '600px', margin: '0 auto', padding: '20px' }}>
        {loading ? (
          <div style={{ textAlign: 'center', padding: '50px' }}>
            <div className="skeleton" style={{ height: '400px', borderRadius: '8px' }}></div>
          </div>
        ) : (
          <>
            {mockPosts.map((post, index) => (
              <div
                key={post.id}
                ref={index === mockPosts.length - 1 ? lastItemRef : null}
              >
                <FeedPost post={post} />
              </div>
            ))}
            
            {isLoading && (
              <div style={{ textAlign: 'center', padding: '20px' }}>
                Loading more posts...
              </div>
            )}
            
            {!hasMore && mockPosts.length > 0 && (
              <div style={{ textAlign: 'center', padding: '20px', color: '#8e8e8e' }}>
                You've seen all posts! ✨
              </div>
            )}
          </>
        )}
      </div>
    </div>
  );
};

export default ConsumerDashboard;