import React from 'react';
import { BrowserRouter, Routes, Route, Navigate } from 'react-router-dom';
import { AuthProvider, useAuth } from './contexts/AuthContext';
import Login from './pages/Login/index';
import CreatorDashboard from './pages/CreatorDashboard/index';
import ConsumerDashboard from './pages/ConsumerDashboard/index';

// This component handles all routes
function AppRoutes() {
  const { user, isAuthenticated, role } = useAuth();
  
  console.log('AppRoutes - isAuthenticated:', isAuthenticated, 'role:', role);
  
  // If not authenticated, show login
  if (!isAuthenticated) {
    return <Login />;
  }
  
  // If authenticated, show dashboard based on role
  if (role === 'creator') {
    return <CreatorDashboard />;
  }
  
  if (role === 'consumer') {
    return <ConsumerDashboard />;
  }
  
  // Fallback
  return <Login />;
}

function App() {
  return (
    <BrowserRouter>
      <AuthProvider>
        <AppRoutes />
      </AuthProvider>
    </BrowserRouter>
  );
}

export default App;