import React, { createContext, useContext, useState } from 'react';

const AuthContext = createContext();

export const useAuth = () => {
  return useContext(AuthContext);
};

export const AuthProvider = ({ children }) => {
  const [user, setUser] = useState(null);
  const [isAuthenticated, setIsAuthenticated] = useState(false);
  const [role, setRole] = useState(null);

  const login = async (email, password) => {
    console.log('Login attempt:', email);
    
    if (email === 'creator@example.com') {
      const userData = { username: 'Creator', email };
      setUser(userData);
      setRole('creator');
      setIsAuthenticated(true);
      console.log('Creator logged in - isAuthenticated set to true');
      return { success: true, role: 'creator' };
    } 
    else if (email === 'consumer@example.com') {
      const userData = { username: 'Consumer', email };
      setUser(userData);
      setRole('consumer');
      setIsAuthenticated(true);
      console.log('Consumer logged in - isAuthenticated set to true');
      return { success: true, role: 'consumer' };
    }
    
    console.log('Login failed');
    return { success: false };
  };

  const logout = () => {
    console.log('Logging out');
    setUser(null);
    setRole(null);
    setIsAuthenticated(false);
  };

  const value = {
    user,
    isAuthenticated,
    role,
    login,
    logout,
    isCreator: role === 'creator',
    isConsumer: role === 'consumer',
  };

  console.log('AuthProvider state:', { isAuthenticated, role });

  return (
    <AuthContext.Provider value={value}>
      {children}
    </AuthContext.Provider>
  );
};