import React, { useEffect } from 'react';
import { useAuth } from '../../contexts/AuthContext';

const CreatorDashboard = () => {
  const { user, logout } = useAuth();

  useEffect(() => {
    console.log('Creator Dashboard mounted');
  }, []);

  return (
    <div style={{ 
      minHeight: '100vh',
      background: '#fafafa'
    }}>
      <div style={{ 
        background: 'white',
        padding: '15px 30px',
        display: 'flex',
        justifyContent: 'space-between',
        alignItems: 'center',
        borderBottom: '1px solid #dbdbdb'
      }}>
        <h1 style={{ margin: 0, fontSize: '24px' }}>Creator Dashboard</h1>
        <button 
          onClick={logout}
          style={{
            padding: '8px 16px',
            backgroundColor: '#ed4956',
            color: 'white',
            border: 'none',
            borderRadius: '5px',
            cursor: 'pointer'
          }}
        >
          Logout
        </button>
      </div>
      <div style={{ padding: '30px', maxWidth: '800px', margin: '0 auto' }}>
        <h2>Welcome, {user?.username || 'Creator'}! 👋</h2>
        <p style={{ fontSize: '16px', color: '#666' }}>
          You are now logged in as a Creator.
        </p>
        <div style={{
          marginTop: '30px',
          padding: '40px',
          border: '2px dashed #ddd',
          borderRadius: '10px',
          textAlign: 'center',
          backgroundColor: '#fff'
        }}>
          <p>📹 Video uploader will appear here</p>
        </div>
      </div>
    </div>
  );
};

export default CreatorDashboard;